import java.io.*;import java.util.*;class Result {static class Edge implements Comparable<Edge> {int u, v, w;public Edge(int u, int v, int w) {this.u = u;this.v = v;this.w = w;}public int compareTo(Edge other) {if (this.w != other.w) return Integer.compare(this.w, other.w);return Integer.compare(this.u + this.v + this.w, other.u + other.v + other.w);}}static class DSU {int[] parent;public DSU(int n) {parent = new int[n + 1];for (int i = 0; i <= n; i++) parent[i] = i;}public int find(int i) {if (parent[i] == i) return i;return parent[i] = find(parent[i]);}public boolean union(int i, int j) {int rootI = find(i);int rootJ = find(j);if (rootI != rootJ) {parent[rootI] = rootJ;return true;}return false;}}public static int kruskals(int gNodes, List<Integer> gFrom, List<Integer> gTo, List<Integer> gWeight) {List<Edge> edges = new ArrayList<>();for (int i = 0; i < gFrom.size(); i++) {edges.add(new Edge(gFrom.get(i), gTo.get(i), gWeight.get(i)));}Collections.sort(edges);DSU dsu = new DSU(gNodes);int totalWeight = 0;for (Edge e : edges) {if (dsu.union(e.u, e.v)) {totalWeight += e.w;}}return totalWeight;}}public class Solution {public static void main(String[] args) throws IOException {BufferedReader bufferedReader = new BufferedReader(new InputStreamReader(System.in));BufferedWriter bufferedWriter = new BufferedWriter(new FileWriter(System.getenv("OUTPUT_PATH")));String[] gNodesEdges = bufferedReader.readLine().replaceAll("\\s+$", "").split(" ");int gNodes = Integer.parseInt(gNodesEdges[0]);int gEdges = Integer.parseInt(gNodesEdges[1]);List<Integer> gFrom = new ArrayList<>();List<Integer> gTo = new ArrayList<>();List<Integer> gWeight = new ArrayList<>();for (int i = 0; i < gEdges; i++) {String[] gFromToWeight = bufferedReader.readLine().replaceAll("\\s+$", "").split(" ");gFrom.add(Integer.parseInt(gFromToWeight[0]));gTo.add(Integer.parseInt(gFromToWeight[1]));gWeight.add(Integer.parseInt(gFromToWeight[2]));}int res = Result.kruskals(gNodes, gFrom, gTo, gWeight);bufferedWriter.write(String.valueOf(res));bufferedWriter.newLine();bufferedReader.close();bufferedWriter.close();}}